import React from 'react';

export function ProjectChip({ project, employeeId, onRemove }) {
  return (
    <span className="project-chip">
      {project.title}
      <button
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          onRemove(employeeId, project.id);
        }}
        className="remove-btn"
        title="Удалить проект"
      >
        ×
      </button>
    </span>
  );
}