import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, addDoc, deleteDoc, doc, query, orderBy } from 'firebase/firestore';

export function useFirebaseTeams() {
  const [teams, setTeams] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, 'teams'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setTeams(data);
      setLoading(false);
    }, (error) => {
      console.error("Ошибка загрузки команд:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const addTeam = async (name) => {
    try {
      await addDoc(collection(db, 'teams'), {
        name,
        createdAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Ошибка добавления команды:", error);
    }
  };

  const removeTeam = async (id) => {
    try {
      await deleteDoc(doc(db, 'teams', id));
      // Здесь можно также обновить сотрудников, убрать у них эту команду
      // Но пока оставим как есть – сотрудники останутся с несуществующим teamId
      // Лучше потом добавить清理ку
    } catch (error) {
      console.error("Ошибка удаления команды:", error);
    }
  };

  return { teams, addTeam, removeTeam, loading };
}