import React from 'react';
import './TeamStatsSidebar.css';

const TeamStatsSidebar = ({ teams, employees }) => {
  const teamCounts = teams.map(team => {
    const count = employees.filter(emp => emp.teamId === team.id).length;
    return { name: team.name, count };
  });
  const unassignedCount = employees.filter(emp => !emp.teamId).length;
  if (unassignedCount > 0) {
    teamCounts.push({ name: 'Без команды', count: unassignedCount });
  }

  const maxCount = Math.max(...teamCounts.map(t => t.count), 1);

  return (
    <div className="stats-sidebar">
      <h3>Статистика команд</h3>
      {teamCounts.map((item, idx) => (
        <div key={idx} className="stat-sidebar-item">
          <span className="stat-sidebar-label">{item.name}</span>
          <div className="bar-sidebar-container">
            <div
              className="bar-sidebar"
              style={{ width: `${(item.count / maxCount) * 100}%` }}
            >
              {item.count}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default TeamStatsSidebar;