import React, { useEffect, useState } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { ProjectChip } from './ProjectChip';
import './EmployeeCard.css';

function computeTenure(startDate) {
  if (!startDate) return null;
  const start = new Date(startDate);
  const now = new Date();
  const years = now.getFullYear() - start.getFullYear();
  const months = now.getMonth() - start.getMonth();
  let totalMonths = years * 12 + months;
  if (now.getDate() < start.getDate()) totalMonths--;
  if (totalMonths < 0) totalMonths = 0;
  const y = Math.floor(totalMonths / 12);
  const m = totalMonths % 12;
  if (y > 0) return `${y} г ${m} мес`;
  return `${m} мес`;
}

export function EmployeeCard({
  employee,
  assignedProjects,
  onRemoveAssignment,
  onRemoveEmployee,
  teams,
  onUpdateEmployeeTeam,
  onUpdateEmployeeStartDate,
  onUpdateEmployeePhone,
  onUpdateEmployeeName,
  projects,
  onAddAssignment
}) {
  const { setNodeRef, isOver } = useDroppable({
    id: employee.id,
    data: { employeeId: employee.id }
  });

  const [startDate, setStartDate] = useState(employee.startDate || '');
  const [phoneDigits, setPhoneDigits] = useState(() => extractPhoneDigits(employee.phone));
  const [phoneDirty, setPhoneDirty] = useState(false);
  const [isEditingName, setIsEditingName] = useState(false);
  const [nameDraft, setNameDraft] = useState(employee.name || '');
  const [addProjectId, setAddProjectId] = useState('');

  function extractPhoneDigits(phoneValue) {
    const digits = String(phoneValue || '').replace(/\D/g, '');
    if (!digits) return '';
    // Если пришло в формате +7XXXXXXXXXX (11 цифр) или 8XXXXXXXXXX — убираем первый префикс
    if (digits.length >= 11 && (digits[0] === '7' || digits[0] === '8')) return digits.slice(1, 11);
    // Иначе берём последние 10 цифр (частично тоже можно)
    if (digits.length > 10) return digits.slice(-10);
    return digits;
  }

  const currentE164 = (() => {
    const d = extractPhoneDigits(employee.phone);
    return d.length ? '+7' + d : null;
  })();

  // Синхронизируем значение из Firestore, но только если пользователь не правит поле
  useEffect(() => {
    if (phoneDirty) return;
    setPhoneDigits(extractPhoneDigits(employee.phone));
  }, [employee.phone, phoneDirty]);

  useEffect(() => {
    if (isEditingName) return;
    setNameDraft(employee.name || '');
  }, [employee.name, isEditingName]);

  const savePhone = (valueToSave) => {
    if (!onUpdateEmployeePhone) return Promise.resolve();
    const next = valueToSave && valueToSave.length ? valueToSave : null;
    const current = currentE164;
    if (next === current) return Promise.resolve();
    return onUpdateEmployeePhone(employee.id, next);
  };

  const commitPhone = () => {
    const nextE164 = phoneDigits.length ? '+7' + phoneDigits : null;
    return savePhone(nextE164)
      .then(() => setPhoneDirty(false))
      .catch(() => {
        // оставляем dirty=true, чтобы значение не "прыгало" обратно
      });
  };

  const handleRemoveEmployee = () => {
    if (window.confirm(`Удалить сотрудника ${employee.name}?`)) {
      onRemoveEmployee(employee.id);
    }
  };

  const saveName = () => {
    if (!onUpdateEmployeeName) {
      setIsEditingName(false);
      return;
    }
    const next = nameDraft.trim();
    if (!next || next === (employee.name || '')) {
      setNameDraft(employee.name || '');
      setIsEditingName(false);
      return;
    }
    Promise.resolve(onUpdateEmployeeName(employee.id, next)).finally(() => setIsEditingName(false));
  };

  const handleTeamChange = (e) => {
    const newTeamId = e.target.value === '' ? null : e.target.value;
    onUpdateEmployeeTeam(employee.id, newTeamId);
  };

  const handleStartDateChange = (e) => {
    const date = e.target.value;
    setStartDate(date);
    onUpdateEmployeeStartDate(employee.id, date);
  };

  const tenure = computeTenure(employee.startDate);

  return (
    <div
      ref={setNodeRef}
      className={`employee-card ${isOver ? 'drag-over' : ''}`}
    >
      <div className="employee-header">
        <div className="employee-name">
          {isEditingName ? (
            <input
              className="employee-name-input"
              value={nameDraft}
              onChange={(e) => setNameDraft(e.target.value)}
              onBlur={saveName}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  saveName();
                }
                if (e.key === 'Escape') {
                  e.preventDefault();
                  setNameDraft(employee.name || '');
                  setIsEditingName(false);
                }
              }}
              autoFocus
              placeholder="ФИО"
            />
          ) : (
            <button
              type="button"
              className="employee-name-view"
              onClick={() => setIsEditingName(true)}
              title="Нажмите чтобы изменить ФИО"
            >
              <span>{employee.name}</span>
              <span className="employee-edit-icon">✎</span>
            </button>
          )}
        </div>
        <div className="employee-controls">
          <select
            className="team-select"
            value={employee.teamId || ''}
            onChange={handleTeamChange}
          >
            <option value="">Без команды</option>
            {teams.map(team => (
              <option key={team.id} value={team.id}>{team.name}</option>
            ))}
          </select>
          <button onClick={handleRemoveEmployee} className="remove-employee-btn" title="Удалить сотрудника">✕</button>
        </div>
      </div>

      <div className="employee-tenure">
        <label>Дата начала работы: </label>
        <input
          type="date"
          value={startDate}
          onChange={handleStartDateChange}
        />
        {tenure && <span className="tenure-value"> (Стаж: {tenure})</span>}
      </div>

      <div className="employee-phone">
        <label>Телефон: </label>
        <div className="employee-phone-editor">
          <span className="phone-prefix">+7</span>
          <input
            type="tel"
            inputMode="numeric"
            value={phoneDigits}
            onChange={(e) => {
              setPhoneDirty(true);
              setPhoneDigits(extractPhoneDigits(e.target.value).slice(0, 10));
            }}
            placeholder="___ ___ __ __"
            onBlur={() => {
              commitPhone();
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                commitPhone();
                e.currentTarget.blur();
              }
              if (e.key === 'Escape') {
                e.preventDefault();
                setPhoneDirty(false);
                setPhoneDigits(extractPhoneDigits(employee.phone));
                e.currentTarget.blur();
              }
            }}
          />
        </div>
      </div>

      {onAddAssignment && projects && (
        <div className="employee-add-project">
          <label>Добавить проект:</label>
          <div className="employee-add-project-row">
            <select
              value={addProjectId}
              onChange={(e) => setAddProjectId(e.target.value)}
              className="employee-add-project-select"
            >
              <option value="">Выберите проект…</option>
              {projects
                .filter((p) => !assignedProjects.some((ap) => ap.id === p.id))
                .map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.title}
                  </option>
                ))}
            </select>
            <button
              type="button"
              className="employee-add-project-btn"
              disabled={!addProjectId}
              onClick={() => {
                if (!addProjectId) return;
                onAddAssignment(employee.id, addProjectId);
                setAddProjectId('');
              }}
            >
              Добавить
            </button>
          </div>
        </div>
      )}

      <div className="projects-list">
        {assignedProjects.map(project => (
          <ProjectChip
            key={project.id}
            project={project}
            employeeId={employee.id}
            onRemove={onRemoveAssignment}
          />
        ))}
        {assignedProjects.length === 0 && (
          <span className="empty-projects">Нет проектов</span>
        )}
      </div>
    </div>
  );
}