import React from 'react';
import { EmployeeCard } from './EmployeeCard';
import './EmployeesPanel.css';

const generateColorFromString = (str) => {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  const colors = [
    '#e53935', '#d81b60', '#8e24aa', '#5e35b1', 
    '#3949ab', '#1e88e5', '#039be5', '#00acc1',
    '#00897b', '#43a047', '#7cb342', '#c0ca33',
    '#fdd835', '#ffb300', '#fb8c00', '#f4511e',
    '#6d4c41', '#757575', '#546e7a', '#ec407a',
    '#ab47bc', '#7e57c2', '#5c6bc0', '#42a5f5',
    '#26c6da', '#26a69a', '#66bb6a', '#9ccc65'
  ];
  const index = Math.abs(hash) % colors.length;
  return colors[index];
};

const getTeamColor = (teamName) => {
  if (!teamName) return '#667eea';
  const name = teamName.toLowerCase();
  if (name.includes('лид')) return '#4caf50';
  if (name.includes('аналитик')) return '#2196f3';
  if (name.includes('медиа')) return '#e91e63';
  if (name.includes('кадр')) return '#ff9800';
  if (name.includes('адаптац')) return '#ff9800';
  if (name.includes('подбор') && name.includes('flex')) return '#9c27b0';
  if (name.includes('подбор') && name.includes('base')) return '#673ab7';
  if (name.includes('подбор')) return '#9c27b0';
  if (name.includes('преборд') || name.includes('пребординг')) return '#009688';
  if (name.includes('pco') || name.includes('рсо') || name.includes('рco')) return '#ff5722';
  if (name.includes('привлечен') || name.includes('студент')) return '#00bcd4';
  return generateColorFromString(teamName);
};

export function EmployeesPanel({
  employees,
  teams,
  assignments,
  projects,
  onRemoveAssignment,
  onAddAssignment,
  onAddEmployee,
  onRemoveEmployee,
  onUpdateEmployeeTeam,
  onUpdateEmployeeStartDate,
  onUpdateEmployeePhone,
  onUpdateEmployeeName,
  onAddTeam,
  onRemoveTeam,
  teamFilter,
  setTeamFilter,
  searchTerm,
  setSearchTerm
}) {
  const [newName, setNewName] = React.useState('');
  const [newTeamName, setNewTeamName] = React.useState('');

  const getProjectsForEmployee = (employeeId) => {
    const assignedIds = assignments
      .filter(a => a.employeeId === employeeId)
      .map(a => a.projectId);
    return projects.filter(p => assignedIds.includes(p.id));
  };

  const handleAddEmployee = () => {
    if (newName.trim()) {
      onAddEmployee(newName.trim());
      setNewName('');
    }
  };

  const handleAddTeam = () => {
    if (newTeamName.trim()) {
      onAddTeam(newTeamName.trim());
      setNewTeamName('');
    }
  };

  // Фильтрация сотрудников: по имени ИЛИ по названию проекта
  const filteredEmployees = employees.filter(emp => {
    const lowerSearch = searchTerm.toLowerCase();
    if (!searchTerm.trim()) return true;
    if (emp.name.toLowerCase().includes(lowerSearch)) return true;
    const empProjects = getProjectsForEmployee(emp.id);
    return empProjects.some(proj => proj.title.toLowerCase().includes(lowerSearch));
  });

  // Фильтр по команде
  let finalEmployees = filteredEmployees;
  if (teamFilter !== 'all') {
    finalEmployees = finalEmployees.filter(emp => emp.teamId === teamFilter);
  }

  // Группировка по командам (показываем все команды, даже пустые)
  const employeesByTeam = {};
  teams.forEach(team => {
    const teamEmployees = finalEmployees.filter(emp => emp.teamId === team.id);
    employeesByTeam[team.id] = { team, employees: teamEmployees };
  });
  const unassignedEmployees = finalEmployees.filter(emp => !emp.teamId);

  return (
    <div className="employees-panel">
      <h3>Сотрудники</h3>

      <div className="add-form">
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          placeholder="Имя нового сотрудника"
        />
        <button onClick={handleAddEmployee}>Добавить</button>
      </div>

      <div className="add-form">
        <input
          type="text"
          value={newTeamName}
          onChange={(e) => setNewTeamName(e.target.value)}
          placeholder="Название новой команды"
        />
        <button onClick={handleAddTeam}>Создать команду</button>
      </div>

      <div className="search-form">
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="🔍 Поиск по имени или названию проекта..."
        />
      </div>

      <div className="filter-section">
        <label>Команда:</label>
        <select value={teamFilter} onChange={(e) => setTeamFilter(e.target.value)}>
          <option value="all">Все</option>
          {teams.map(team => (
            <option key={team.id} value={team.id}>{team.name}</option>
          ))}
        </select>
      </div>

      <div className="teams-list">
        {Object.values(employeesByTeam).map(({ team, employees }) => (
          <div 
            key={team.id} 
            className="team-section"
            style={{ borderLeftColor: getTeamColor(team.name) }}
          >
            <div 
              className="team-header"
              style={{ backgroundColor: getTeamColor(team.name) + '20' }}
            >
              <h4 style={{ color: getTeamColor(team.name) }}>{team.name}</h4>
              <button
                className="remove-team-btn"
                onClick={() => {
                  if (window.confirm(`Удалить команду "${team.name}"?`)) {
                    onRemoveTeam(team.id);
                  }
                }}
                title="Удалить команду"
              >
                ✕
              </button>
            </div>
            <div className="team-employees">
              {employees.length > 0 ? (
                employees.map(employee => (
                  <EmployeeCard
                    key={employee.id}
                    employee={employee}
                    assignedProjects={getProjectsForEmployee(employee.id)}
                    onRemoveAssignment={onRemoveAssignment}
                    onRemoveEmployee={onRemoveEmployee}
                    teams={teams}
                    projects={projects}
                    onAddAssignment={onAddAssignment}
                    onUpdateEmployeeTeam={onUpdateEmployeeTeam}
                    onUpdateEmployeeStartDate={onUpdateEmployeeStartDate}
                    onUpdateEmployeePhone={onUpdateEmployeePhone}
                    onUpdateEmployeeName={onUpdateEmployeeName}
                  />
                ))
              ) : (
                <span className="empty-team">Нет сотрудников</span>
              )}
            </div>
          </div>
        ))}
        {unassignedEmployees.length > 0 && (
          <div className="team-section">
            <h4>Без команды</h4>
            <div className="team-employees">
              {unassignedEmployees.map(employee => (
                <EmployeeCard
                  key={employee.id}
                  employee={employee}
                  assignedProjects={getProjectsForEmployee(employee.id)}
                  onRemoveAssignment={onRemoveAssignment}
                  onRemoveEmployee={onRemoveEmployee}
                  teams={teams}
                  projects={projects}
                  onAddAssignment={onAddAssignment}
                  onUpdateEmployeeTeam={onUpdateEmployeeTeam}
                  onUpdateEmployeeStartDate={onUpdateEmployeeStartDate}
                  onUpdateEmployeePhone={onUpdateEmployeePhone}
                  onUpdateEmployeeName={onUpdateEmployeeName}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}